int characterReplacement(string s, int k) {
    int cnt[26] = {}; int best = 0, maxFreq = 0, l = 0;
    for (int r = 0; r < s.size(); r++) {
        maxFreq = max(maxFreq, ++cnt[s[r]-'A']);
        if (r - l + 1 - maxFreq > k)          // need more replacements than budget
            cnt[s[l]-'A']--, l++;             // LAZY single-step shrink
        best = max(best, r - l + 1);
    }
    return best;
}

